/* eslint-disable */
// ⚠️ Generated by project-memory — overwritten on every run. Do not edit.
//
// Feature tests import { test, expect, step, credentials } from '../fixture'.
// While a test runs, this records:
//   - every step('...') with pass/fail and duration
//   - every fetch/XHR API call (request + response, sensitive keys masked)
//   - a video of the browser
// and writes them to the run file that project-memory turns into docs.

import { test as base, expect, type Request } from '@playwright/test';
import fs from 'node:fs';
import path from 'node:path';

export { expect };

/** Test account from project-memory.config.ts → auth */
export const credentials = {
  username: process.env.PM_USERNAME ?? '',
  password: process.env.PM_PASSWORD ?? '',
};

type StepRecord = {
  index: number;
  title: string;
  status: 'passed' | 'failed';
  durationMs: number;
  error?: string;
};

type ApiRecord = {
  step: number | null;
  method: string;
  path: string;
  query: string;
  status: number;
  startedMs: number;
  durationMs: number;
  request?: unknown;
  response?: unknown;
  error?: string;
};

const API_PREFIX = process.env.PM_API_PREFIX ?? '/api';
const MASK = (process.env.PM_MASK ?? 'password,token,secret,authorization')
  .split(',')
  .map((s) => s.trim().toLowerCase())
  .filter(Boolean);
const MAX_ITEMS = 3;
const MAX_TEXT = 500;

let steps: StepRecord[] = [];
let currentStep: number | null = null;

const stripAnsi = (s: string) => s.replace(/\x1b\[[0-9;]*m/g, '');

/** A documented user action. Wrap every action in the test with this. */
export async function step<T>(title: string, body: () => Promise<T>): Promise<T> {
  const record: StepRecord = { index: steps.length + 1, title, status: 'passed', durationMs: 0 };
  steps.push(record);
  currentStep = record.index;
  const started = Date.now();
  try {
    return await base.step(title, body);
  } catch (error) {
    record.status = 'failed';
    record.error = stripAnsi(String((error as Error)?.message ?? error))
      .split('\n')
      .filter(Boolean)
      .slice(0, 3)
      .join(' ');
    throw error;
  } finally {
    record.durationMs = Date.now() - started;
  }
}

const isSensitive = (key: string) => MASK.some((m) => key.toLowerCase().includes(m));

function mask(value: unknown): unknown {
  if (Array.isArray(value)) {
    const items: unknown[] = value.slice(0, MAX_ITEMS).map(mask);
    if (value.length > MAX_ITEMS) items.push(`… ${value.length - MAX_ITEMS} more`);
    return items;
  }
  if (value && typeof value === 'object') {
    const out: Record<string, unknown> = {};
    for (const [key, v] of Object.entries(value)) out[key] = isSensitive(key) ? '***' : mask(v);
    return out;
  }
  if (typeof value === 'string' && value.length > MAX_TEXT) return value.slice(0, MAX_TEXT) + '…';
  return value;
}

function parseBody(text: string | null | undefined): unknown {
  if (!text) return undefined;
  try {
    return JSON.parse(text);
  } catch {
    return text.length > MAX_TEXT ? text.slice(0, MAX_TEXT) + '…' : text;
  }
}

function maskQuery(search: string): string {
  if (!search) return '';
  const params = new URLSearchParams(search);
  for (const key of [...params.keys()]) if (isSensitive(key)) params.set(key, '***');
  const s = params.toString();
  return s ? `?${s}` : '';
}

function isApi(req: Request): boolean {
  const type = req.resourceType();
  if (type !== 'fetch' && type !== 'xhr') return false;
  if (!API_PREFIX) return true;
  if (/^https?:\/\//.test(API_PREFIX)) return req.url().startsWith(API_PREFIX);
  try {
    return new URL(req.url()).pathname.startsWith(API_PREFIX);
  } catch {
    return false;
  }
}

export const test = base.extend<{ _projectMemory: void }>({
  contextOptions: async ({ contextOptions }, use) => {
    const dir = process.env.PM_VIDEO_DIR;
    await use(dir ? { ...contextOptions, recordVideo: { dir, size: { width: 1280, height: 720 } } } : contextOptions);
  },

  _projectMemory: [
    async ({ page }, use, testInfo) => {
      steps = [];
      currentStep = null;
      const testStarted = Date.now();
      const apis: ApiRecord[] = [];
      const pending: Promise<void>[] = [];
      const seen = new Map<Request, { started: number; step: number | null }>();

      page.on('request', (req) => {
        if (isApi(req)) seen.set(req, { started: Date.now(), step: currentStep });
      });

      page.on('response', (res) => {
        const req = res.request();
        const meta = seen.get(req);
        if (!meta) return;
        pending.push(
          (async () => {
            const url = new URL(req.url());
            const record: ApiRecord = {
              step: meta.step,
              method: req.method(),
              path: url.pathname,
              query: maskQuery(url.search),
              status: res.status(),
              startedMs: meta.started - testStarted,
              durationMs: Date.now() - meta.started,
              request: mask(parseBody(req.postData())),
            };
            try {
              record.response = mask(parseBody(await res.text()));
            } catch {
              // body not available (redirect, aborted, …)
            }
            apis.push(record);
          })(),
        );
      });

      page.on('requestfailed', (req) => {
        const meta = seen.get(req);
        if (!meta) return;
        const url = new URL(req.url());
        apis.push({
          step: meta.step,
          method: req.method(),
          path: url.pathname,
          query: maskQuery(url.search),
          status: 0,
          startedMs: meta.started - testStarted,
          durationMs: Date.now() - meta.started,
          request: mask(parseBody(req.postData())),
          error: req.failure()?.errorText ?? 'request failed',
        });
      });

      await use();

      await Promise.allSettled(pending);
      apis.sort((a, b) => a.startedMs - b.startedMs);

      const runFile = process.env.PM_RUN_FILE;
      if (!runFile) return;
      let video: string | null = null;
      try {
        video = (await page.video()?.path()) ?? null;
      } catch {
        video = null;
      }
      fs.mkdirSync(path.dirname(runFile), { recursive: true });
      fs.writeFileSync(
        runFile,
        JSON.stringify(
          {
            title: testInfo.title,
            status: testInfo.status ?? (testInfo.errors.length ? 'failed' : 'passed'),
            error: testInfo.errors[0]?.message ? stripAnsi(testInfo.errors[0].message).split('\n')[0] : undefined,
            startedAt: new Date(testStarted).toISOString(),
            durationMs: Date.now() - testStarted,
            steps,
            apis,
            video,
          },
          null,
          2,
        ),
      );
    },
    { auto: true },
  ],
});
